#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    long long T;
    cin >> N >> K >> T;

    vector<int> P(N), G(N);
    for (int &x : P) cin >> x;
    for (int &x : G) cin >> x;

    if (K == N) {
        cout << accumulate(P.begin(), P.end(), 0) << '\n';
        return 0;
    }

    int D = min(K, N - K);
    int maxReward = 9 * K;
    int width = maxReward + 1;
    int size = (2 * D + 1) * width;
    const int INF = 1e9;

    auto indexOf = [&](int d, int reward) {
        return (d + D) * width + reward;
    };

    vector<int> cur(size, INF), nxt(size, INF);
    vector<int> touchedCur, touchedNxt;

    cur[indexOf(0, 0)] = 0;
    touchedCur.push_back(indexOf(0, 0));

    int initialPrefix = 0;

    for (int i = 1; i <= N; ++i) {
        for (int idx : touchedNxt) nxt[idx] = INF;
        touchedNxt.clear();

        int prevPrefix = initialPrefix;
        int newPrefix = prevPrefix + G[i - 1];

        int prevFLo = max(0, K - (N - (i - 1)));
        int prevFHi = min(K, i - 1);
        int prevDLo = prevPrefix - prevFHi;
        int prevDHi = prevPrefix - prevFLo;

        int nextFLo = max(0, K - (N - i));
        int nextFHi = min(K, i);
        int nextDLo = newPrefix - nextFHi;
        int nextDHi = newPrefix - nextFLo;

        for (int d = prevDLo; d <= prevDHi; ++d) {
            int f = prevPrefix - d;
            int rMax = 9 * f;

            int d0 = d + G[i - 1];
            int d1 = d + G[i - 1] - 1;

            bool valid0 = d0 >= nextDLo && d0 <= nextDHi;
            bool valid1 = d1 >= nextDLo && d1 <= nextDHi;

            for (int r = 0; r <= rMax; ++r) {
                int cost = cur[indexOf(d, r)];
                if (cost == INF) continue;

                if (valid0) {
                    int nc = cost + abs(d0);
                    if (nc <= T) {
                        int idx = indexOf(d0, r);
                        if (nxt[idx] == INF) touchedNxt.push_back(idx);
                        if (nc < nxt[idx]) nxt[idx] = nc;
                    }
                }

                if (valid1) {
                    int nc = cost + abs(d1);
                    if (nc <= T) {
                        int nr = r + P[i - 1];
                        int idx = indexOf(d1, nr);
                        if (nxt[idx] == INF) touchedNxt.push_back(idx);
                        if (nc < nxt[idx]) nxt[idx] = nc;
                    }
                }
            }
        }

        initialPrefix = newPrefix;
        swap(cur, nxt);
        swap(touchedCur, touchedNxt);
    }

    int answer = 0;
    for (int r = 0; r <= maxReward; ++r) {
        if (cur[indexOf(0, r)] <= T) answer = r;
    }

    cout << answer << '\n';
    return 0;
}
